(() => {
 const data=window.SCHOOL_DATA;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 window.partnershipDetail=r=>r.collaboration?`<section class="partner-contribution" aria-label="合作計畫與課程的連結"><h2>這個計畫，讓學習多走了哪一步？</h2><div class="partner-flow">${[['協力支持',r.collaboration.role],['走進課程',r.collaboration.course],['作品與學習',r.collaboration.outputs]].map(([t,v],i)=>`<div><span>0${i+1} / ${t}</span><p>${esc(v)}</p></div>`).join('')}</div></section>`:'';
 window.partnershipMedia=r=>r.video?`<section class="partner-video"><div><p class="eyebrow">WATCH THE STORY</p><h2>${esc(r.video.title)}</h2><p>${esc(r.video.text)}</p></div><a class="button primary" href="${esc(r.video.url)}" target="_blank" rel="noopener noreferrer" data-video-title="${esc(r.video.title)}">▶ 觀看圓夢紀錄影片</a></section>`:'';
 window.partnershipCallout=()=>`<section class="partner-callout"><div><p class="eyebrow">一起把學習的路走寬</p><h2>每一份支持，都走進孩子的課堂</h2><p>文化採集、歌謠錄製、科學探究與工藝分享，看看合作計畫如何連起課程和成果。</p></div><a class="button" href="partnerships.html">走進合作計畫 →</a></section>`;
 window.showPartnerships=()=>{
 const projects=data.partnershipIds.map(id=>data.resources.find(r=>r.id===id)),main=document.getElementById('main');
 main.innerHTML=`<header class="page-heading"><div class="breadcrumb"><a href="index.html">首頁</a><span>/</span><a href="stories.html">成果廣場</a><span>/</span><span>合作計畫</span></div><p class="eyebrow">114學年度的協力網絡 · 連到115年度的下一步</p><h1>一起，把山海的學習走得更遠。</h1><p>一本書、一首歌、一個研究問題、一枚手作書籤。學校、部落與伙伴，把不同的支持帶進同一段學習旅程。</p></header><div class="page-body partner-page"><section class="partner-opening"><div><p class="eyebrow">從課程到作品</p><h2>把計畫連起來，<br>看見孩子怎麼學。</h2><p>實驗教育的課程是共同的路徑：文化採集留下記憶，音樂讓族語被聽見，科學探究追問生活，工藝與展演把發現分享出去。</p><a class="text-link" href="resource.html?id=PLAN-002">接著看115・116螺旋式課程 →</a></div><div class="partner-opening-images">${[projects[0].photos[2],projects[1].cover,projects[2].photos[0]].map(id=>`<img src="${esc(data.assets[id].src)}" alt="文化採集、歌謠舞台與教師研習" decoding="async">`).join('')}</div></section><nav class="topic-nav" aria-label="合作計畫入口">${projects.map((r,i)=>`<a href="#partner-${i+1}">${['國泰圓夢','多元智能','原資中心','東博工作坊'][i]}</a>`).join('')}<a href="stories.html">展演與比賽成果 ↗</a></nav><section class="partner-network"><h2>不同的支持，同一張學習地圖</h2><div class="doc-table-scroll"><table class="doc-table"><thead><tr><th scope="col">計畫</th><th scope="col">怎麼支持課程</th><th scope="col">作品與學習路徑</th></tr></thead><tbody>${projects.map((r,i)=>`<tr><th scope="row"><a href="#partner-${i+1}">${['國泰圓夢','多元智能','原資中心子計畫','東博潛能覺醒艙'][i]}</a><small>${esc(r.termLabel)}</small></th><td>${esc(r.collaboration.course)}</td><td>${esc(r.collaboration.outputs)}</td></tr>`).join('')}</tbody></table></div></section><div class="partner-stories">${projects.map((r,i)=>`<article class="partner-story" id="partner-${i+1}"><a class="partner-story-image ${r.coverFit==='contain'?'image-contain':''}" href="resource.html?id=${r.id}"><img src="${esc(data.assets[r.cover].src)}" alt="${esc(r.photoLabel)}" loading="lazy"></a><div class="partner-story-copy"><p class="eyebrow">0${i+1} / ${esc(r.termLabel)}</p><h2><a href="resource.html?id=${r.id}">${esc(r.title)}</a></h2><p>${esc(r.summary)}</p><p class="partner-outcome">${esc(r.collaboration.outputs)}</p><div class="tags">${r.topics.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><a class="button" href="resource.html?id=${r.id}">走進計畫與圖文故事 →</a></div></article>`).join('')}</div><section class="partner-next"><h2>作品完成了，故事還在往前走</h2><p>沿著舞台、比賽或教案，繼續看看同一段學習的不同模樣。</p><div class="detail-actions"><a class="button primary" href="stories.html">看全部展演與比賽成果 →</a><a class="button" href="lessons.html">按主題找教案 →</a></div></section></div>`;
 };
})();
